/* eslint @typescript-eslint/no-require-imports: "off" */
// Print rollback-only SQL vectors generated by the TypeScript preview helper.
const fs = require("node:fs")
const path = require("node:path")
const ts = require("typescript")
const source = fs.readFileSync(path.join(__dirname, "../src/lib/utils/plate-expiration.ts"), "utf8")
const compiled = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText
const moduleObject = { exports: {} }
new Function("module", "exports", compiled)(moduleObject, moduleObject.exports)
const { plateExpiration, parseDateOnly } = moduleObject.exports
const rows = []
for (const year of [2024, 2025, 2026, 2028, 2100, 2400]) {
  for (let month = 1; month <= 12; month++) {
    for (const day of [1, 15, 28, 29, 30, 31]) {
      const issued = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`
      if (!parseDateOnly(issued)) continue
      for (let digit = 0; digit <= 9; digit++) {
        rows.push(`('${issued}'::date,'ZZ-PLATE-${digit}','${plateExpiration(issued, `ZZ-PLATE-${digit}`)}'::date)`)
      }
    }
  }
}
process.stdout.write(`BEGIN;
DO $$ DECLARE v_mismatches integer; BEGIN
  SELECT count(*) INTO v_mismatches FROM (VALUES ${rows.join(",\n")}) AS vectors(issued,plate,expected)
  WHERE mtop.plate_expiration(issued,plate) IS DISTINCT FROM expected;
  IF v_mismatches <> 0 THEN RAISE EXCEPTION '% TypeScript/PostgreSQL mismatches', v_mismatches; END IF;
  RAISE NOTICE 'PASS: ${rows.length} TypeScript/PostgreSQL date and plate vectors';
END $$;
ROLLBACK;
`)
